def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    # Check if start or goal are walls
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    import heapq
    heap = []
    heapq.heappush(heap, (0, start))
    visited = set()
    predecessors = {}

    while heap:
        current_dist, current_pos = heapq.heappop(heap)

        if current_pos == goal:
            # Reconstruct path
            path = []
            while current_pos in predecessors:
                path.append(current_pos)
                current_pos = predecessors[current_pos]
            path.append(start)
            return path[::-1]

        if current_pos in visited:
            continue

        visited.add(current_pos)
        row, col = current_pos

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols:
                if grid[new_row][new_col] == '.':
                    new_pos = (new_row, new_col)
                    if new_pos not in visited and new_pos not in predecessors:
                        heapq.heappush(heap, (current_dist + 1, new_pos))
                        predecessors[new_pos] = current_pos

    return []

