def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]
    INF = float('inf')
    # Initialize distance and predecessor matrices
    dist = [[INF] * cols for _ in range(rows)]
    prep = [[None] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0
    V = rows * cols
    # Bellman-Ford algorithm
    for _ in range(V - 1):
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == '#':
                    continue
                current_dist = dist[i][j]
                # Check all four directions
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
