        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = (r, c)
                    if (nr, nc) == goal:
                        # Reconstruct path
                        path = []
                        current = (nr, nc)
                        while current:
                            path.append(current)
                            current = parent.get(current, None)
                        return path[::-1]
