import heapq
import random

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    heap = []
    heapq.heappush(heap, (random.random(), start, [start]))
    visited.add(start)
    while heap:
        _, current, path = heapq.heappop(heap)
        if current == goal:
            return path
        for dr, dc in directions:
            nr, nc = (current[0] + dr, current[1] + dc)
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    new_path = path + [(nr, nc)]
                    heapq.heappush(heap, (random.random(), (nr, nc), new_path))
    return []

